def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Nanoseconds since midnight
    :type nanoseconds: int
    :param tz: Optional timezone info
    :type tz: datetime.tzinfo, None
    :return: datetime.time
    """
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an integer") from exc

    if ns < 0:
        raise ValueError("nanoseconds cannot be negative")

    total_seconds, remaining_ns = divmod(ns, 1_000_000_000)
    micros = remaining_ns // 1000
    total_seconds %= 86400
    hour, remainder = divmod(total_seconds, 3600)
    minute, second = divmod(remainder, 60)

    if tz and hasattr(tz, 'utcoffset'):
        return time(hour, minute, second, micros, tzinfo=tz)
    return time(hour, minute, second, micros)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        from datetime import timedelta as _timedelta
    except Exception:
        raise ImportError("Could not import datetime.timedelta")
    if not isinstance(value, _timedelta):
        raise TypeError(f"dehydrate_timedelta expects a datetime.timedelta, got {type(value).__name__}")
    return value.total_seconds()

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        # Use the total_seconds method to obtain the duration in seconds
        total = value.total_seconds()
    except Exception as e:
        raise TypeError("dehydrate_timedelta expects a datetime.timedelta instance") from e
    return int(total)

