        import traceback
        import os

        def _reduce_path(path, depth):
            try:
                parts = path.split(os.sep)
                if len(parts) > depth:
                    return os.sep.join(parts[-depth:])
                return path
            except Exception:
                return path

        def _format_traceback(tb, level_limit):
            frames = traceback.extract_tb(tb)
            formatted = []
            for idx, frame in enumerate(frames[:level_limit]):
                fname = _reduce_path(frame.filename, max_path_level)
                formatted.append(
                    f'  File "{fname}", line {frame.lineno}, in {frame.name}'
                )
            return formatted

        def _describe_exception(exc):
            parts = [f'{exc.__class__.__name__}: {exc}']
            parts.extend(_format_traceback(exc.__traceback__, max_level - 1))
            return parts

        # Validate inputs
        if not isinstance(e, BaseException):
            raise TypeError("e must be an exception instance")

        if not isinstance(max_level, int) or max_level <= 0:
            raise ValueError("max_level must be a positive integer")

        if not isinstance(max_path_level, int) or max_path_level <= 0:
            raise ValueError("max_path_level must be a positive integer")

        # Gather exception chain
        result_parts = []
        current_exc = e
        while current_exc and len(result_parts) < max_level:
            result_parts.extend(_describe_exception(current_exc))
            # Stop if we have reached the level limit
            remaining = max_level - len(result_parts)
            if remaining <= 0:
                break

            # Move to the next exception in the chain (cause or context)
            next_exc = getattr(current_exc, '__cause__', None) or getattr(
                current_exc, '__context__', None
            )
            if next_exc is None or not isinstance(next_exc, BaseException):
                break
            result_parts.append("Caused by:")
            current_exc = next_exc

        return "\n".join(result_parts)

