    # Main logic ---------------------------------------------------------
    # ------------------------------------------------------------------
    import re

    # Validate input SQL type
    if isinstance(sql, bytes):
        # Cannot reliably process binary SQL; just return as is
        return sql, list(many_params)

    if not isinstance(sql, str):
        raise TypeError("sql must be a str or bytes instance")

