        return sql, list(many_params)

    # If styles are identical, no conversion needed
    if in_style == out_style:
        return sql, list(many_params)

    # Only support qmark in_style for now
    if in_style != "qmark":
        # Unsupported input style; raise informative error
        raise NotImplementedError(
