    new_sql = _placeholder_replacer(sql, placeholder_count, out_style)

    # Convert parameter sets
    out_params_list: List[Union[Dict[Union[str, int], Any], Sequence[Any]]] = []

    for idx, param_set in enumerate(many_params):
        # Validate param_set type
        if _is_sequence(param_set):
            # Sequence: values must match number of placeholders
            if len(param_set) != placeholder_count:
                raise ValueError(
