    except Exception as exc:
        raise RuntimeError(f"Required modules not available: {exc}")

    root_inventory = None
    differences = []
    errors = []

    for idx, dir_name in enumerate(version_dirs):
        inv_path = os.path.join(dir_name, 'inventory.xml')
        if not os.path.exists(inv_path):
            errors.append(f"Missing inventory file in directory '{dir_name}'.")
            continue
        try:
            tree = ET.parse(inv_path)
            root = tree.getroot()
        except Exception as exc:
            errors.append(f"Failed to parse inventory in '{dir_name}': {exc}")
            continue

        # Build a mapping of file path → digest
        current_inv = {}
        # Accept either <file> tags or whatever the schema uses
        for fe in root.findall('.//file'):
            path = fe.get('path')
            digest = fe.get('digest')
            if path and digest:
                current_inv[path] = digest

        if idx == 0:
            # The first inventory is considered the “root” reference
            root_inventory = current_inv
            continue

        if root_inventory is None:
            errors.append(f"Cannot compare inventory in '{dir_name}' – root inventory is missing.")
            continue

        # Compare files
        for path, digest in current_inv.items():
            root_digest = root_inventory.get(path)
            if root_digest is None:
