    def _load_inventory(inv_path):
        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            raise ValueError(f"Inventory file not found: {inv_path}")
        except json.JSONDecodeError as e:
