def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated
    string.
    '''
    try:
        if parser is None:
            return ''
        # Retrieve the list of actions from the parser.  _actions is a protected
        # attribute but is the standard way argparse stores actions.
        actions = getattr(parser, '_actions', None)
        if not isinstance(actions, (list, tuple)):
            return ''
        flags = []
        for action in actions:
            try:
                opt_strs = getattr(action, 'option_strings', None)
                if opt_strs:
                    flags.extend(opt_strs)
            except Exception:
                # If any action has an unexpected structure, ignore it and continue.
                continue
        return ' '.join(flags)
    except Exception:
        # In the unlikely event that parser is not a proper argparse instance or
        # some unexpected error occurs, return an empty string rather than
        # raising an exception to preserve stability.
        return ''

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic type checking
    try:
        # Import inside function to keep method dependency minimal
        from argparse import ArgumentParser
    except Exception:
        raise RuntimeError('argparse module is required but could not be imported')

    if not isinstance(parser, ArgumentParser):
