        except AttributeError:
            continue
        if option_strings:
            flags.extend(option_strings)
    return " ".join(flags)

import argparse

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    # Example global option(s) – can be extended as needed
    parser.add_argument('--verbose', action='store_true', help='Enable verbose output')
    # Create subparsers container (empty; subparsers can be added by the caller if needed)
    subparsers = parser.add_subparsers(dest='subparser')
    # Note: If specific subparsers are added elsewhere, their arguments will be captured in the
    # resulting Namespace under 'subparser' key.
    try:
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
    except SystemExit:  # argparse throws SystemExit on parse errors (e.g., --help)
        # If parsing fails, return an empty mapping; the caller can decide how to handle it.
        return {}
    result = {'global': namespace}
    # If a subparser was provided, create a separate namespace for it
    if getattr(namespace, 'subparser', None):
