def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    if script is None:
        return ""

    if isinstance(script, str):
        # Remove any common leading whitespace
        script = textwrap.dedent(script)
        lines = script.splitlines()
    elif isinstance(script, (list, tuple)):
        lines = [str(item) for item in script]
    else:
        raise ValueError("script must be a string, list, or tuple")

    # Strip each line and ignore blank lines
    cleaned = [line.strip() for line in lines if line.strip()]

    if not cleaned:
        return ""

    return seperator.join(cleaned)

