                                    points[i][last_field] = point[last_field] * factor
                        elif isinstance(point, dict) and last_field in point:
                            points[i][last_field] = point[last_field] * factor
                    except Exception:
                        # Skip points that cannot be scaled
                        continue

    # Rescale associated errors
    error_attrs = ['errors', 'point_errors', 'data_errors']
    for attr in error_attrs:
        if hasattr(self, attr):
