        for iparam, imp in zip(iface_params, impl_params):
            if iparam.kind != imp.kind:
                errors.append(
                    f"Signature mismatch for {name!r}: parameter {iparam.name!r} "
                    f"has kind {iparam.kind} in interface but {imp.kind} in candidate."
                )
