    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        raise TypeError("Expected a string, got %r" % (type(text).__name__,))
    # Regex patterns for URLs (http, https, ftp) and www. prefixes
    url_pattern = re.compile(
        r'(?P<prefix>https?://|ftp://)'
        r'(?P<domain>[^\s/]+(?:/[^\s]*)?)',
        re.IGNORECASE)
    www_pattern = re.compile(
        r'(?P<prefix>www\.)'
        r'(?P<domain>[^\s/]+(?:/[^\s]*)?)',
        re.IGNORECASE)
    # Regex pattern for email addresses (simple version)
    email_pattern = re.compile(
        r'(?P<email>[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})',
        re.IGNORECASE)

    def replace_url(match):
        try:
            href = match.group('prefix') + match.group('domain')
            text = href
            return f'<a href="{href}" target="_blank" rel="nofollow">{text}</a>'
        except Exception:
            return match.group(0)

    def replace_www(match):
        try:
            href = 'http://' + match.group('domain')
            text = match.group(0)
            return f'<a href="{href}" target="_blank" rel="nofollow">{text}</a>'
        except Exception:
            return match.group(0)

    def replace_email(match):
        try:
            email = match.group('email')
            return f'<a href="mailto:{email}">{email}</a>'
        except Exception:
            return match.group(0)

    # First replace full URLs
    text = url_pattern.sub(replace_url, text)
    # Then replace www prefixes
    text = www_pattern.sub(replace_www, text)
    # Finally replace email addresses
    text = email_pattern.sub(replace_email, text)

    return text

